<div class="ss-page">
    @livewire('inc.header')
    <main class="ss-container" x-data="{
            filtersOpen: false,
            openFilters() { this.filtersOpen = true; this.$nextTick(() => this.$refs.filterClose.focus()); },
            closeFilters() { if (!this.filtersOpen) return; this.filtersOpen = false; this.$refs.filterToggle.focus(); },
            trapFilterFocus(event) {
                if (!this.filtersOpen) return;
                const controls = [...this.$refs.filters.querySelectorAll('button, input')];
                const first = controls[0];
                const last = controls[controls.length - 1];
                if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
                if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
            }
        }" @keydown.escape.window="closeFilters()" @resize.window="if (window.innerWidth > 800) filtersOpen = false">
        <div class="ss-breadcrumb"><a href="/">Trang chủ</a> › Cửa hàng</div>
        <div class="ss-heading"><div><h1>Cửa Hàng Gaming Gear & Phím Cơ</h1><p>Hiển thị {{ $products->total() }} sản phẩm</p></div><div class="ss-controls"><input type="search" wire:model.live.debounce.350ms="search" placeholder="Tìm sản phẩm..." aria-label="Tìm sản phẩm"><select wire:model.live="sort" aria-label="Sắp xếp"><option value="featured">Nổi bật nhất</option><option value="price-asc">Giá: Thấp đến Cao</option><option value="price-desc">Giá: Cao đến Thấp</option><option value="discount">Khuyến mãi</option></select></div></div>
        <button class="ss-filter-toggle" x-ref="filterToggle" type="button" @click="openFilters()" :aria-expanded="filtersOpen.toString()" aria-controls="shop-filters">Lọc sản phẩm</button>
        <div class="ss-filter-backdrop" x-cloak x-show="filtersOpen" @click="closeFilters()"></div>
        <div class="ss-layout"><aside id="shop-filters" x-ref="filters" :role="filtersOpen ? 'dialog' : null" :aria-modal="filtersOpen ? 'true' : null" aria-label="Bộ lọc sản phẩm" @keydown.tab="trapFilterFocus($event)" :class="{ 'is-open': filtersOpen }"><div class="ss-filter-heading"><h2>Bộ lọc sản phẩm</h2><button class="ss-filter-close" x-ref="filterClose" type="button" @click="closeFilters()" aria-label="Đóng bộ lọc">×</button></div><h3>DANH MỤC</h3><button type="button" wire:click="selectCategory('')" @click="closeFilters()" class="{{ !$categorySlug ? 'active' : '' }}">Tất cả sản phẩm</button>@foreach($categories as $category)<button type="button" wire:click="selectCategory('{{ $category->slug }}')" @click="closeFilters()" class="{{ $categorySlug === $category->slug ? 'active' : '' }}">{{ $category->name }}</button>@endforeach<h3>KHOẢNG GIÁ</h3>@foreach(['' => 'Tất cả mức giá', 'under_500' => 'Dưới 500.000₫', '500_1000' => '500.000₫ – 1.000.000₫', '1000_2000' => '1.000.000₫ – 2.000.000₫', 'over_2000' => 'Trên 2.000.000₫'] as $value => $label)<label><input type="radio" wire:model.live="priceRange" value="{{ $value }}" @change="closeFilters()"> {{ $label }}</label>@endforeach</aside>
        <div>@if($products->isEmpty())<div class="ss-empty"><h2>Không tìm thấy sản phẩm phù hợp</h2><p>Hãy thử từ khóa hoặc bộ lọc khác.</p></div>@else<div class="ss-grid">@foreach($products as $product)@php $productImages=$product->images ?: []; $firstVariant=$product->variants->firstWhere('stock','in_stock') ?: $product->variants->first(); $cardImage = $firstVariant?->image ?: ($productImages[0] ?? null); @endphp<article class="ss-card"><div class="ss-image"><a href="/product/{{ $product->slug }}" aria-label="{{ $product->name }}">@if(!empty($cardImage))<img src="{{ asset('storage/'.$cardImage) }}" alt="{{ $product->name }}">@endif</a><button type="button" class="ss-quick" wire:click="$dispatch('open-product-quick-view', { productId: {{ $product->id }} })"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg> Xem nhanh</button></div><a class="ss-name" href="/product/{{ $product->slug }}">{{ $product->name }}</a><div class="ss-card-bottom"><strong>{{ number_format($firstVariant?->price ?? $product->price, 0, ',', '.') }}₫</strong><button type="button" wire:click="$dispatch('open-product-quick-view', { productId: {{ $product->id }} })" aria-label="Chọn phiên bản {{ $product->name }}"><span>Chọn phiên bản</span></button></div></article>@endforeach</div><div class="ss-pagination">{{ $products->links('livewire.store-pagination') }}</div>@endif</div></div>
    </main>
