transition:filter .2s}.ss-image span{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);padding:8px 12px;border-radius:99px;background:#fffe;opacity:0;white-space:nowrap;font-size:12px}.ss-card:hover .ss-image img{filter:blur(3px)}.ss-card:hover .ss-image span{opacity:1}.ss-name{font-size:14px;font-weight:600;line-height:20px;min-height:40px;margin:12px 0}.ss-card-bottom{margin-top:auto;padding-top:10px;border-top:1px solid #eee;display:flex;align-items:center;justify-content:space-between}.ss-card-bottom strong{font-size:14px}.ss-card-bottom a{width:32px;height:32px;display:grid;place-items:center;background:#171717;color:#fff;border-radius:50%}.ss-pagination{margin-top:24px}.ss-empty{text-align:center;border:1px dashed #ddd;border-radius:16px;padding:40px}.ss-empty h2{font-size:18px}.ss-empty p{color:#777}@media(max-width:800px){.ss-layout{grid-template-columns:1fr}.ss-layout aside{display:flex;flex-wrap:wrap;gap:8px}.ss-layout aside h2,.ss-layout aside h3{width:100%}.ss-layout aside button,.ss-layout aside label{width:auto}.ss-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ss-heading{align-items:start;flex-direction:column}.ss-heading h1{font-size:25px}}@media(max-width:480px){.ss-grid{gap:10px}.ss-card{padding:8px}.ss-name{font-size:12px}.ss-controls{width:100%}.ss-controls input{width:50%}.ss-controls select{width:50%}}
        .ss-image>a{display:block;width:100%;height:100%}.ss-image .ss-quick{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:inline-flex;align-items:center;gap:6px;border:0;padding:8px 14px;border-radius:99px;background:#fffe;opacity:0;white-space:nowrap;font-size:12px;cursor:pointer}.ss-image .ss-quick svg{width:15px;height:15px;flex:none}.ss-card:hover .ss-quick,.ss-card:focus-within .ss-quick{opacity:1}.ss-card-bottom button{width:32px;height:32px;padding:8px;display:grid;place-items:center;background:#171717;color:#fff;border:0;border-radius:50%;cursor:pointer}.ss-card-bottom button svg{width:16px;height:16px}
